#include "fuzz.h"

#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/* Registry generated by the Makefile: one ts_fuzz_<name>(void) per fuzz_*.c. */
extern const char *const ts_fuzz_names[];
extern void (*const ts_fuzz_funcs[])(void);
extern const size_t ts_fuzz_count;

#define MAX_INPUT 8192
#define DEFAULT_SEED 0x7473707070636667ULL

static const char *volatile g_name = "";
static volatile unsigned long long g_seed;
static volatile unsigned g_iter;
static volatile sig_atomic_t g_reported;

static unsigned long long env_u64(const char *k, unsigned long long dflt)
{
    const char *v = getenv(k);
    return v && *v ? strtoull(v, NULL, 0) : dflt;
}

static void put(const char *s) { size_t n = strlen(s); if (write(2, s, n) < 0) {} }

static void putu(unsigned long long v)
{
    char b[24];
    int i = 23;
    b[i] = 0;
    do { b[--i] = (char)('0' + v % 10); v /= 10; } while (v);
    put(b + i);
}

/* Async-signal-safe report; also the sanitizers' death callback. */
static void report(void)
{
    if (g_reported) return;
    g_reported = 1;
    put("\nFUZZ FAULT: ");
    put(g_name);
    put(" seed=");
    putu(g_seed);
    put(" iteration=");
    putu(g_iter);
    put("\nreproduce: TS_FUZZ_SEED=");
    putu(g_seed);
    put(" TS_FUZZ_START=");
    putu(g_iter);
    put(" TS_FUZZ_ITERS=1 build/fuzz/fuzz_all ");
    put(g_name);
    put("\n");
}

static void on_signal(int sig)
{
    (void)sig;
    report();
    _exit(1);
}

extern void __sanitizer_set_death_callback(void (*)(void)) __attribute__((weak_import));

static void install_handlers(void)
{
    static const int sigs[] = { SIGSEGV, SIGBUS, SIGILL, SIGFPE, SIGABRT, SIGTRAP };
    size_t i;
    for (i = 0; i < sizeof sigs / sizeof sigs[0]; i++) signal(sigs[i], on_signal);
    if (__sanitizer_set_death_callback) __sanitizer_set_death_callback(report);
}

static unsigned long long splitmix(unsigned long long *s)
{
    unsigned long long z = (*s += 0x9e3779b97f4a7c15ULL);
    z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9ULL;
    z = (z ^ (z >> 27)) * 0x94d049bb133111ebULL;
    return z ^ (z >> 31);
}

static size_t rnd(unsigned long long *s, size_t n)   /* uniform-ish in [0, n) */
{
    return n ? (size_t)(splitmix(s) % n) : 0;
}

static size_t mutate(unsigned long long *rs, uint8_t *buf, size_t len,
                     const uint8_t *const *seeds, const size_t *seedlens, size_t nseeds)
{
    unsigned nmut = 1 + (unsigned)rnd(rs, 4), m;
    for (m = 0; m < nmut; m++) {
        switch (rnd(rs, 5)) {
        case 0:   /* bit flip */
            if (len) buf[rnd(rs, len)] ^= (uint8_t)(1u << rnd(rs, 8));
            break;
        case 1:   /* byte substitution, biased towards structural characters */
            if (len) {
                static const char special[] = "{}[]\",:\\ -0123456789.eEtrufalsn/u";
                size_t at = rnd(rs, len);
                buf[at] = rnd(rs, 2) ? (uint8_t)special[rnd(rs, sizeof special - 1)]
                                     : (uint8_t)rnd(rs, 256);
            }
            break;
        case 2:   /* truncate */
            if (len) len = rnd(rs, len);
            break;
        case 3: { /* insert 1-8 random bytes */
            size_t k = 1 + rnd(rs, 8), at = rnd(rs, len + 1), i;
            if (len + k <= MAX_INPUT) {
                memmove(buf + at + k, buf + at, len - at);
                for (i = 0; i < k; i++) buf[at + i] = (uint8_t)rnd(rs, 256);
                len += k;
            }
            break;
        }
        default: { /* splice a chunk of a seed (or of this input) in */
            const uint8_t *src;
            size_t slen, from, k, at;
            uint8_t tmp[MAX_INPUT];
            if (nseeds && rnd(rs, 2)) {
                size_t si = rnd(rs, nseeds);
                src = seeds[si]; slen = seedlens[si];
            } else {
                memcpy(tmp, buf, len);
                src = tmp; slen = len;
            }
            if (slen == 0) break;
            from = rnd(rs, slen);
            k = 1 + rnd(rs, slen - from);
            if (k > 64) k = 64;
            at = rnd(rs, len + 1);
            if (len + k <= MAX_INPUT) {
                memmove(buf + at + k, buf + at, len - at);
                memcpy(buf + at, src + from, k);
                len += k;
            }
            break;
        }
        }
    }
    return len;
}

void ts_fuzz_run(const char *name, void (*target)(const uint8_t *, size_t),
                 const uint8_t *const *seeds, const size_t *seedlens,
                 size_t nseeds, unsigned iterations)
{
    unsigned long long base = env_u64("TS_FUZZ_SEED", DEFAULT_SEED);
    unsigned start = (unsigned)env_u64("TS_FUZZ_START", 0);
    unsigned n = (unsigned)env_u64("TS_FUZZ_ITERS", iterations);
    unsigned i;
    static uint8_t buf[MAX_INPUT];

    install_handlers();
    g_name = name;
    g_seed = base;
    g_reported = 0;
    for (i = start; i < start + n; i++) {
        unsigned long long rs = base ^ ((unsigned long long)i * 0xd6e8feb86659fd93ULL);
        size_t len = 0, si;
        uint8_t *exact;
        g_iter = i;
        if (nseeds) {
            si = rnd(&rs, nseeds);
            len = seedlens[si] < MAX_INPUT ? seedlens[si] : MAX_INPUT;
            memcpy(buf, seeds[si], len);
        }
        len = mutate(&rs, buf, len, seeds, seedlens, nseeds);
        /* Exact-size heap copy: any overread by the target is an ASan error. */
        exact = (uint8_t *)malloc(len ? len : 1);
        if (!exact) { put("fuzz: out of memory\n"); _exit(2); }
        memcpy(exact, buf, len);
        target(exact, len);
        free(exact);
    }
    printf("fuzz %s: %u iterations, no faults\n", name, n);
    fflush(stdout);
}

int main(int argc, char **argv)
{
    size_t i;
    int ran = 0;
    for (i = 0; i < ts_fuzz_count; i++) {
        if (argc > 1 && strcmp(argv[1], ts_fuzz_names[i]) != 0) continue;
        ts_fuzz_funcs[i]();
        ran++;
    }
    if (!ran) { fprintf(stderr, "fuzz: no such target\n"); return 2; }
    return 0;
}
